describe('Modal Scroll Prevention', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should prevent page scrolling when modal is open', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal is visible
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');

    // Scroll to bottom of page
    cy.get('[data-testid="page-content"]').scrollTo('bottom');

    // Verify page scroll position is at bottom
    cy.get('[data-testid="page-content"]').should('have.scrollHeight', cy.get('[data-testid="page-content"]').scrollTop() + cy.get('[data-testid="page-content"]').scrollHeight);

    // Verify modal is still visible and not scrollable
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="modal-content"]').should('be.visible');
    cy.get('[data-testid="page-content"]').should('not.have.scrollHeight');

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should allow scrolling when modal is closed', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Scroll to top of page
    cy.get('[data-testid="page-content"]').scrollTo('top');

    // Verify page scroll position is at top
    cy.get('[data-testid="page-content"]').should('have.scrollHeight', cy.get('[data-testid="page-content"]').scrollTop() + cy.get('[data-testid="page-content"]').scrollHeight);

    // Close modal
    cy.get('[data-testid="close-modal-btn"]').click();

    // Verify page scroll is restored
    cy.get('[data-testid="page-content"]').should('have.scrollHeight');
    cy.get('[data-testid="page-content"]').should('have.scrollTop', 0);
  });
});
